function GachaponNumberOfRoundsDialog:AddButtonClick()
    SetButtonAction(self.FontStyleButton1 , Bind(self, self.DrawRookieCall))
end

function GachaponNumberOfRoundsDialog:DrawRookieCall()
    GameUtils.Request(Interfaces.CallDrawRookie,{rewardId = self.selectIndex} , function(request, response)
        if checkNumber(response.errCode) == 0 then
            local comp = GachaponUtils.GetGachaponComp()
            comp:DrawRookieCall(self._pool)
            GoodsUtils.DrawRewards(response.data.rewards)
            GoodsUtils.ConsumeGoods(response.data.consume, true)
            GachaponUtils.OpenDialogAction(Constants.UITypeIds.UICommonRewardPop, { rewards = response.data.rewards, cb = function()
                self:ToClose()
            end})
        end
    end)
end

function GachaponNumberOfRoundsDialog:ToClose()
    self:DeleteEffectAndStopCo()
    GachaponShared.TabResult = nil
    GachaponShared.PopUp = nil
    --KCookie.Set("DRAW_CARD_POOL_INDEX", checkNumber(self._jumpIndex))
    --todo: 临时改动 测试ResultViewNew
    local comp = GachaponUtils.GetGachaponComp()
    -- 如果在新手中 ， 直接
    return cs_coroutine.start(function()
        local wait = true
        GameUtils.Request(Interfaces.CallHome, {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                wait = response
            end
        end)
        while wait == true do
            coroutine.yield()
        end
        comp:InitialGachapon(wait.data)
        UIModule.BackArgumentDialog()
    end)

    -- self.controller:Close()
end
function GachaponNumberOfRoundsDialog:InitData()
    GameUtils.Request(Interfaces.CallAllRookieCall , {} , function(request, response)
        if checkNumber(response.errCode) == 0 then
            local data = response.data
            self.roundCardDatas = data.roundCardDatas
            self:FirstShowResult()
            self:InitChooseGroup()
        end
    end)
end

function GachaponNumberOfRoundsDialog:GetRoundCardDatas()
    return self.roundCardDatas
end

function GachaponNumberOfRoundsDialog:SetToggleSelectIndex(index)
    if self.selectIndex == index then
        return
    end

    self.selectIndex = index
    self:SwitchRoundCardResult()
end

function GachaponNumberOfRoundsDialog:InitChooseGroup()
    local ChooseGroup = self.ChooseGroup
    local transform = ChooseGroup.transform
    local roundCardDatas = self:GetRoundCardDatas()
    local id = self.controller.Argument.id
    for i = 1 , 10 do
        local toggleCell = transform:Find("ToggleCell" .. i )
        if not isNull(toggleCell) then
            local luaBehaviour =  AddLuaBehaviour(toggleCell.gameObject , "Game.Gachapon.GachaponNumberOfRoundsCell")
            ---@type GachaponNumberOfRoundsCell
            local cell = luaBehaviour.Env
            cell:SetData(roundCardDatas[tostring(i)] ,i , id)
            if i == 1 then
                cell:SetToggleSelect(true)
            end
            cell:InitUI()
            cell:PlayAnimation()
        end
    end
end

function GachaponNumberOfRoundsDialog:FirstShowResult()
    local allData = self:GetRoundCardDatas()[tostring(self.selectIndex)]
    local cnt = #allData
    GachaponUtils.ResizeContent(self.grid, cnt, self.GachaCell)
    -- 添加屏幕遮挡
    UIRaycastBlocker:AddCondition(GachaponConstants.GachaponBlockKeys.GachaponBlockKeys)
    --self.grid.localScale = Vector3(0.9, 0.9, 1)
    -- 更新每个结果单元
    for i = 1, cnt do
        local trans = self.grid:GetChild(i - 1)
        trans.localScale = Vector3(1, 1, 1)
        trans.name = string.format("GachaCell%s", i)

        self:UpdateGachaCell(trans, allData[i], i)
        self:AddGachaCellEvent(trans, allData[i], i)
    end
    -- 播放出场动画
    local co = cs_coroutine.start(function()
        local animName =  "View_Enter_Cell10"
        if self.isBack then
            animName = "View_Enter_Cell10_Return"
        end
        local rootAnim = self.controller.transform:Find("Container/Root").gameObject:GetComponent(typeof(Animator))
        CfUtils.PlayAnimator(rootAnim, animName)

        local gridAnim = self.grid.gameObject:GetComponent(typeof(Animator))
        local gridName = self.isBack and "Grid_Return" or "Grid_Enter"
        CfUtils.PlayAnimator(gridAnim, gridName)
        if self.isBack then
            coroutine.yield(Yielders.EndOfFrame)
        else
            local play10Delay = GachaponConstants.GachaponResultViewAnim.PLAY_10_DELAY
            coroutine.yield(Yielders.GetWaitForSeconds(play10Delay))
        end
        UIRaycastBlocker:RemoveCondition(GachaponConstants.GachaponBlockKeys.GachaponBlockKeys)
    end)
    table.insert(self._loadCo, co)
end

function GachaponNumberOfRoundsDialog:SwitchRoundCardResult()
    local allData = self:GetRoundCardDatas()[tostring(self.selectIndex)]
    --先暂停携程， 删除特效
    self:DeleteEffectAndStopCo()
    for i = 1, 10 do
        local trans = self.grid:GetChild(i - 1)
        self:UpdateGachaCell(trans, allData[i], i)
        self:AddGachaCellEvent(trans, allData[i], i)
    end
end

---@param trans UnityEngine.Transform
---@param card table @ { goodsId:string, num:integer }
---@param pos integer @ (1-len)
function GachaponNumberOfRoundsDialog:AddGachaCellEvent(trans, card, pos)
    local cardId = card.goodsId
    local mainCell = trans:Find("CellMain")
    SetButtonAction(mainCell, function()
        self.controller.Argument.parameters.isBack = true
        GachaponUtils.OpenDetail(cardId)
    end)
end


function GachaponNumberOfRoundsDialog:UpdateGachaCell(trans, card, pos)
    self:StopAllCo()
    local co = cs_coroutine.start(function()
        local cardId = card.goodsId
        local cardVo = CardConfMgr:GetCardByRefId(cardId)
        local mainCell = trans:Find("CellMain")
        local img = mainCell:Find("CardGroup/Card/Role/charact").gameObject:GetComponent(RawImageAlterable)
        ---@type CardSkinVo
        local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardVo.defaultSkin)
        if skinVo then
            local path = skinVo.cardHeadList
            img:LoadSprite(path)
        end
        local swithImages = {
            "CardGroup/Card/ImgBgCard1",
            "CardGroup/Card/ImgBgCard2",
            "CardGroup/Card/ImgBgCard3",
            "CardGroup/Card/ImgBgCard4",
            "CardGroup/Card/AnimRoot/Rare/ImgRareBgMask/ImgRareBg",
            "CardGroup/Card/AnimRoot/Rare/Node/ImgRareIcon",
            "CardGroup/Card/AnimRoot/Rare/Node/ImgRareIcon2"
        }
        --if self.isBack then
        --    ---@type UnityEngine.Animation
        --    local animation  = mainCell:Find("CardGroup/Card/AnimRoot/Rare").gameObject:GetComponent(typeof(CS.UnityEngine.Animation))
        --    if not IsNull(animation) then
        --        animation.enabled = true
        --    end
        --end
        local rare = cardVo.rare
        for i, path in pairs(swithImages) do
            ---@type Game.Native.Common.UISwitchImage
            local uiSwitchImage =  mainCell:Find(path).gameObject:GetComponent(UISwitchImage)
            uiSwitchImage.Status = rare
            uiSwitchImage:Reset()
        end
        ---@type  Game.Native.Common.UISwitchImage
        local ImgElement = mainCell:Find("CardGroup/Card/ProfessionalGroup/ImgElement").gameObject:GetComponent(UISwitchImage)
        ImgElement.Status = checkInt(cardVo.attributeType)

        ---@type  Game.Native.Common.UISwitchImage
        local ImgElement = mainCell:Find("CardGroup/Card/ProfessionalGroup/ImgType").gameObject:GetComponent(UISwitchImage)
        ImgElement.Status = checkInt(cardVo.career)
        local isSSR = cardVo.rare == Constants.RareType.SSR
        KTool.SetActive(mainCell:Find("CardGroup/Card/AnimRoot/Rare/Node/Ssr"), isSSR)
        local rareTip = GachaponConstants.RareTips[cardVo.rare]
        local idlePath = string.format(GachaponConstants.UIEffectCardIdlePath, rareTip)
        local openPath = string.format(GachaponConstants.UIEffectCardOpenPath, rareTip)
        GachaponShared:LoadModel(idlePath)
        GachaponShared:LoadModel(openPath)
        while not GachaponShared:GetModel(idlePath) or not GachaponShared:GetModel(openPath) do
            coroutine.yield(Yielders.EndOfFrame)
        end
        local particleRoot = mainCell:Find("CardGroup/Card/ParticleRoot")
        KTool.SetActive(particleRoot, true)
        local idleIns = GachaponShared:GetModel(idlePath)
        if not isNull(idleIns) then
            idleIns = GameObject.Instantiate(idleIns)
            idleIns.transform:SetParent(particleRoot, false)
            idleIns.name = "idle"
        end
        local openIns = GachaponShared:GetModel(openPath)
        if not isNull(openIns) then
            openIns = GameObject.Instantiate(openIns)
            openIns.transform:SetParent(particleRoot, false)
            openIns.name = "open"
        end
        coroutine.yield(Yielders.EndOfFrame)
        local effectOpen = particleRoot:Find("open")
        if not isNull(effectOpen) then
            KTool.SetActive(effectOpen, true)
        end
        local idleOpen = particleRoot:Find("idle")
        if not isNull(idleOpen) then
            KTool.SetActive(idleOpen, true)
        end
    end)
    if self.updateCellsCo == nil then
        self.updateCellsCo = {}
    end
    table.insert(self.updateCellsCo, co)
end

-- 切换前cell 前先删除 特效节点 暂停携程
function GachaponNumberOfRoundsDialog:DeleteEffectAndStopCo()
    ---@type UnityEngine.GameObject
    local child = nil
    ---@type UnityEngine.GameObject
    local trans = nil
    local effectIns = {}
    for i = 1, 10 do
        trans = self.grid:GetChild(i - 1)
        local mainCell = trans:Find("CellMain")
        ---@type UnityEngine.Transform
        local particleRoot = mainCell:Find("CardGroup/Card/ParticleRoot").transform
        local particleRootCount = particleRoot.childCount
        for j =1 , particleRootCount do
            child = particleRoot.transform:GetChild(j-1)
            if child.name == 'open' or child.name == 'idle' then
                effectIns[#effectIns+1] = child
            end
        end
    end

    for i =1 , #effectIns do
        KTool.SafeDelete(effectIns[i].gameObject,true)
    end
    for i = 1, #self.updateCellsCo do
        cs_coroutine.stop(self.updateCellsCo[i])
    end
    self.updateCellsCo = {}
end

function GachaponNumberOfRoundsDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            GachaponUtils.ResetCameraData(URPCameraController.Instance.uiCamera)
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

return GachaponNumberOfRoundsDialog